//! Keyword tables and lookup (SQL-LEX-01 tables, SQL-LEX-04 lookup; Task 3). Lookup is
//! ASCII-only through an ASCII-upper key on the stack: Turkish `ı`/`İ` and look-alike letters
//! never match a keyword, whatever the process locale.
//!
//! The tables are generated by `cargo xtask gen-sql-tables` from `data/keywords/*.toml`
//! (`src/generated/`), from licence-clean sources only: PostgreSQL's `kwlist.h` inside the
//! vendored libpg_query, what MySQL and MariaDB servers report in
//! `INFORMATION_SCHEMA.KEYWORDS`, and SQLite's public-domain keyword list.

use crate::generated::{keywords_mariadb, keywords_mysql, keywords_pg, keywords_sqlite};
use crate::id::DialectId;
use crate::version::ServerVersion;

/// The shared id space and `kw::*` (generated).
#[path = "generated/keywords_ids.rs"]
mod ids;

pub use ids::kw;

/// A keyword's ID, shared by every dialect's table. Ids follow the words' byte order and
/// change whenever a table gains a word: they are build-local, never persisted.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct KeywordId(pub u16);

/// PostgreSQL's keyword categories (`kwlist.h`); other dialects use `Reserved` and
/// `Unreserved`. MySQL's come from the server's `RESERVED` flag; MariaDB and SQLite report
/// none, so their rows are `Reserved` (an identifier spelled like a keyword gets quoted), as is
/// every `Generic` keyword.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum KwCategory {
    Unreserved,
    ColName,
    TypeFuncName,
    Reserved,
}

/// A keyword of a dialect's table.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct KwEntry {
    pub id: KeywordId,
    pub category: KwCategory,
}

/// One row of a generated table: an entry and the server versions it holds for (`since`
/// inclusive, `until` exclusive, `None` unbounded).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) struct Gated {
    entry: KwEntry,
    since: Option<ServerVersion>,
    until: Option<ServerVersion>,
}

impl Gated {
    pub(crate) const fn new(
        id: KeywordId,
        category: KwCategory,
        since: Option<ServerVersion>,
        until: Option<ServerVersion>,
    ) -> Self {
        Gated {
            entry: KwEntry { id, category },
            since,
            until,
        }
    }

    /// Whether the row holds at `version`; an unknown version reads the newest rows.
    fn holds_at(&self, version: Option<ServerVersion>) -> bool {
        match version {
            None => self.until.is_none(),
            Some(v) => self.since.is_none_or(|s| s <= v) && self.until.is_none_or(|u| v < u),
        }
    }
}

/// A version gate of the generated tables: `major.minor.0`.
pub(crate) const fn at(major: u16, minor: u16) -> Option<ServerVersion> {
    Some(ServerVersion::new(major, minor, 0))
}

type Table = phf::Map<&'static str, &'static [Gated]>;

/// The generated table of `d`; `Generic` has none of its own, and SQL Server, ClickHouse and
/// Oracle none in M3a.
fn table(d: DialectId) -> Option<&'static Table> {
    match d {
        DialectId::Postgres | DialectId::PgWire(_) => Some(&keywords_pg::KEYWORDS),
        DialectId::MySql => Some(&keywords_mysql::KEYWORDS),
        DialectId::MariaDb => Some(&keywords_mariadb::KEYWORDS),
        DialectId::Sqlite => Some(&keywords_sqlite::KEYWORDS),
        DialectId::Generic | DialectId::SqlServer | DialectId::ClickHouse | DialectId::Oracle => {
            None
        }
    }
}

/// The dialects whose shared words are `Generic`'s keywords.
const GENERIC_FROM: [DialectId; 4] = [
    DialectId::Postgres,
    DialectId::MySql,
    DialectId::MariaDb,
    DialectId::Sqlite,
];

/// The longest word the lookup accepts: 32 bytes (alg/10 LEX-04), or the longest keyword when
/// a server reports a longer one.
const MAX_KEY: usize = if ids::MAX_LEN > 32 { ids::MAX_LEN } else { 32 };

/// `word` upper-cased into `buf` (ASCII only): `None` when it is empty, longer than
/// [`MAX_KEY`] or not ASCII, since no keyword is.
fn ascii_upper_key<'b>(word: &str, buf: &'b mut [u8; MAX_KEY]) -> Option<&'b str> {
    let bytes = word.as_bytes();
    if bytes.is_empty() || bytes.len() > MAX_KEY || !bytes.is_ascii() {
        return None;
    }
    let key = &mut buf[..bytes.len()];
    key.copy_from_slice(bytes);
    key.make_ascii_uppercase();
    std::str::from_utf8(key).ok()
}

fn lookup_key(d: DialectId, version: Option<ServerVersion>, key: &str) -> Option<KwEntry> {
    if d == DialectId::Generic {
        // A word every dialect's newest table has; an unknown server is treated as reserving
        // it.
        let mut id = None;
        for from in GENERIC_FROM {
            id = Some(lookup_key(from, None, key)?.id);
        }
        return id.map(|id| KwEntry {
            id,
            category: KwCategory::Reserved,
        });
    }
    table(d)?
        .get(key)?
        .iter()
        .find(|row| row.holds_at(version))
        .map(|row| row.entry)
}

/// `word` as a keyword of `d` on the newest server line Hacivat has a table for: ASCII
/// case-insensitive, never locale-aware; empty, non-ASCII or over-long words are `None`.
pub fn keyword_lookup(d: DialectId, word: &str) -> Option<KwEntry> {
    keyword_lookup_at(d, None, word)
}

/// `word` as a keyword of `d` at `version`: each table's rows carry the server versions they
/// hold for, so a word MySQL 8.4 added is not a keyword of an 8.0 server. An unknown version
/// reads the newest rows ([`keyword_lookup`]); the oldest snapshot's rows are unbounded below,
/// so an older server reads them. PostgreSQL and SQLite have one snapshot each, so every
/// version reads it.
pub fn keyword_lookup_at(
    d: DialectId,
    version: Option<ServerVersion>,
    word: &str,
) -> Option<KwEntry> {
    let mut buf = [0u8; MAX_KEY];
    let key = ascii_upper_key(word, &mut buf)?;
    lookup_key(d, version, key)
}

/// How many words are keywords of `d` on its newest line (what [`keyword_lookup`] finds).
pub fn keyword_count(d: DialectId) -> usize {
    if d == DialectId::Generic {
        return keywords_sqlite::KEYWORDS
            .keys()
            .filter(|key| lookup_key(d, None, key).is_some())
            .count();
    }
    table(d).map_or(0, |t| {
        t.values()
            .filter(|rows| rows.iter().any(|row| row.holds_at(None)))
            .count()
    })
}

/// The canonical upper-case text of `id`; `""` for an id no table has.
pub fn keyword_text(id: KeywordId) -> &'static str {
    ids::TEXT.get(usize::from(id.0)).copied().unwrap_or("")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn gates_are_inclusive_below_and_exclusive_above() {
        let row = Gated::new(kw::SELECT, KwCategory::Reserved, at(8, 4), at(9, 0));
        let v = |a, b, c| Some(ServerVersion::new(a, b, c));
        assert!(!row.holds_at(v(8, 3, 99)));
        assert!(row.holds_at(v(8, 4, 0)));
        assert!(row.holds_at(v(8, 4, 7)));
        assert!(!row.holds_at(v(9, 0, 0)));
        // Bounded above: not on the newest line.
        assert!(!row.holds_at(None));
        assert!(Gated::new(kw::SELECT, KwCategory::Reserved, at(8, 4), None).holds_at(None));
    }

    #[test]
    fn the_key_never_exceeds_the_stack_buffer() {
        let mut buf = [0u8; MAX_KEY];
        // MySQL's `ASSIGN_GTIDS_TO_ANONYMOUS_TRANSACTIONS` is 38 bytes: the bound follows it.
        assert_eq!(MAX_KEY, 38);
        assert_eq!(
            keyword_lookup(DialectId::MySql, "assign_gtids_to_anonymous_transactions")
                .map(|e| keyword_text(e.id)),
            Some("ASSIGN_GTIDS_TO_ANONYMOUS_TRANSACTIONS")
        );
        assert_eq!(
            ascii_upper_key(&"a".repeat(MAX_KEY), &mut buf).map(str::len),
            Some(MAX_KEY)
        );
        assert_eq!(ascii_upper_key(&"a".repeat(MAX_KEY + 1), &mut buf), None);
        assert_eq!(ascii_upper_key("limit", &mut buf), Some("LIMIT"));
        assert_eq!(ascii_upper_key("lımıt", &mut buf), None);
    }

    #[test]
    fn every_keyword_of_every_table_has_its_id_text() {
        for d in GENERIC_FROM {
            let t = table(d).unwrap();
            for (key, rows) in t.entries() {
                for row in rows.iter() {
                    assert_eq!(keyword_text(row.entry.id), *key, "{d:?}");
                }
                assert!(!rows.is_empty(), "{d:?} {key}");
            }
        }
    }
}
